109	function Get-FeishuToken($appId, $appSecret) {
110	  $body = @{ app_id = $appId; app_secret = $appSecret } | ConvertTo-Json
111	  $r = Invoke-RestMethod -Method POST -Uri 'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal' `
112	    -ContentType 'application/json; charset=utf-8' -Body $body
113	  if ($r.code -ne 0) { throw "Feishu token failed: $($r.msg)" }
114	  return $r.tenant_access_token
115	}
116	
117	function Write-FeishuRows($feishu, $rows, $dryRun) {
118	  if ($dryRun) {
119	    Write-Step ("  [dry-run] skip Feishu write, rows={0}" -f $rows.Count)
120	    return @{ written = 0; dryRun = $true }
121	  }
122	  if (-not $rows.Count) { return @{ written = 0; dryRun = $false } }
123	
124	  $token = Get-FeishuToken $feishu.appId $feishu.appSecret
125	  $url = "https://open.feishu.cn/open-apis/bitable/v1/apps/$($feishu.appToken)/tables/$($feishu.tableId)/records/batch_create"
126	  $fieldsUrl = "https://open.feishu.cn/open-apis/bitable/v1/apps/$($feishu.appToken)/tables/$($feishu.tableId)/fields?page_size=100"
127	  $fieldList = Invoke-RestMethod -Method GET -Uri $fieldsUrl -Headers @{ Authorization = "Bearer $token" }
128	  $names = @($fieldList.data.items | ForEach-Object { $_.field_name })
129	
130	  function Pick-Name([string[]]$aliases) {
131	    foreach ($a in $aliases) { if ($names -contains $a) { return $a } }
132	    return $null
133	  }
134	
135	  # UTF-8 field names (same as extension BITABLE_FIELDS)
136	  $utf8 = [System.Text.Encoding]::UTF8
137	  $A_DATE = @($utf8.GetString([byte[]](0xE6,0x97,0xA5,0xE6,0x9C,0x9F)))
138	  $A_STORE = @($utf8.GetString([byte[]](0xE5,0xBA,0x97,0xE9,0x93,0xBA)))
139	  $A_STORE_ID = @($utf8.GetString([byte[]](0xE5,0xBA,0x97,0xE9,0x93,0xBA,0x49,0x44)))
140	  $A_CAMPAIGN = @(
141	    $utf8.GetString([byte[]](0xE5,0x93,0x81,0xE5,0x90,0x8D)),
142	    $utf8.GetString([byte[]](0xE5,0xB9,0xBF,0xE5,0x91,0x8A,0xE7,0xB3,0xBB,0xE5,0x88,0x97,0xE5,0x90,0x8D,0xE7,0xA7,0xB0))
143	  )
144	  $A_SPEND = @(
145	    $utf8.GetString([byte[]](0xE5,0xB9,0xBF,0xE5,0x91,0x8A,0xE8,0x8A,0xB1,0xE8,0xB4,0xB9)),
146	    $utf8.GetString([byte[]](0xE6,0x88,0x90,0xE6,0x9C,0xAC))
147	  )
148	  $A_ORDERS = @($utf8.GetString([byte[]](0xE9,0x94,0x80,0xE9,0x87,0x8F)))
149	  $A_ROI = @('ROI')
150	  $A_REVENUE = @(
151	    $utf8.GetString([byte[]](0xE9,0x94,0x80,0xE5,0x94,0xAE,0xE9,0xA2,0x9D)),
152	    $utf8.GetString([byte[]](0xE6,0x80,0xBB,0xE6,0x94,0xB6,0xE5,0x85,0xA5))
153	  )
154	  $A_SCRAPED = @($utf8.GetString([byte[]](0xE6,0x8A,0x93,0xE5,0x8F,0x96,0xE6,0x97,0xB6,0xE9,0x97,0xB4)))
155	  $A_URL = @($utf8.GetString([byte[]](0xE6,0x95,0xB0,0xE6,0x8D,0xAE,0xE6,0xBA,0x90,0x55,0x52,0x4C)))
156	  $A_STATUS = @($utf8.GetString([byte[]](0xE7,0x8A,0xB6,0xE6,0x80,0x81)))
157	
158	  $fn = @{
159	    date      = Pick-Name $A_DATE
160	    store     = Pick-Name $A_STORE
161	    storeId   = Pick-Name $A_STORE_ID
162	    campaign  = Pick-Name $A_CAMPAIGN
163	    spend     = Pick-Name $A_SPEND
164	    orders    = Pick-Name $A_ORDERS
165	    roi       = Pick-Name $A_ROI
166	    revenue   = Pick-Name $A_REVENUE
167	    scrapedAt = Pick-Name $A_SCRAPED
168	    sourceUrl = Pick-Name $A_URL
169	    status    = Pick-Name $A_STATUS
170	  }
171	
172	  if (-not $fn.campaign -or -not $fn.store) {
173	    throw ("Feishu fields incomplete. Have: {0}" -f ($names -join ', '))
174	  }
175	
176	  $records = @()
177	  foreach ($row in $rows) {
178	    $fields = @{}
179	    if ($fn.date) {
180	      $dt = [DateTime]::ParseExact($row.date, 'yyyy-MM-dd', $null)
181	      $fields[$fn.date] = [DateTimeOffset]::new($dt).ToUnixTimeMilliseconds()
182	    }
183	    if ($fn.store) { $fields[$fn.store] = $row.store }
184	    if ($fn.storeId) { $fields[$fn.storeId] = $row.storeId }
185	    if ($fn.campaign) { $fields[$fn.campaign] = $row.campaign }
186	    if ($fn.spend) { $fields[$fn.spend] = [double]$row.spend }
187	    if ($fn.orders) { $fields[$fn.orders] = [double]$row.orders }
188	    if ($fn.roi) { $fields[$fn.roi] = [double]$row.roi }
189	    if ($fn.revenue) { $fields[$fn.revenue] = [double]$row.revenue }
190	    if ($fn.scrapedAt) { $fields[$fn.scrapedAt] = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds() }
191	    if ($fn.sourceUrl) { $fields[$fn.sourceUrl] = $row.sourceUrl }
192	    if ($fn.status) { $fields[$fn.status] = $row.status }
193	    $records += @{ fields = $fields }
194	  }
195	
196	  $bodyBytes = [System.Text.Encoding]::UTF8.GetBytes((@{ records = $records } | ConvertTo-Json -Depth 8 -Compress))
197	  $resp = Invoke-RestMethod -Method POST -Uri $url -Headers @{ Authorization = "Bearer $token" } `
198	    -ContentType 'application/json; charset=utf-8' -Body $bodyBytes
199	  if ($resp.code -ne 0) {
200	    throw ("Feishu write failed: code={0} msg={1}" -f $resp.code, $resp.msg)
201	  }
202	  return @{ written = $records.Count; dryRun = $false }
203	}
204	
205	# --- main ---
206	function Invoke-Ziniao([string[]]$CliArgs) {
207	  $prev = $ErrorActionPreference
208	  $ErrorActionPreference = 'Continue'
209	  try {
210	    $out = & ziniao-cli @CliArgs 2>&1
211	    $text = ($out | ForEach-Object { "$_" }) -join "`n"
212	    return $text
213	  } finally {
214	    $ErrorActionPreference = $prev
215	  }
216	}
217	
218	Write-Step "check ziniao-cli..."
219	$doctorText = Invoke-Ziniao @('doctor')
220	if ($doctorText -notmatch 'ZClaw|Bridge|ok|OK|通过') {
221	  Write-Host $doctorText
222	  # soft warn only
223	}
224	
225	Write-Step "list stores (dynamic)..."
226	$listRaw = Invoke-Ziniao @('store', 'list', '--format', 'json')
227	if ($listRaw -match '(?s)\{[\s\S]*"ok"\s*:\s*true[\s\S]*\}') {
228	  $listRaw = $Matches[0]
229	}
230	$listObj = $listRaw | ConvertFrom-Json
231	if (-not $listObj.ok) { throw "store list failed: $listRaw" }
232	$all = @($listObj.data.items)
233	Write-Step ("ziniao stores total: {0}" -f $all.Count)
234	
235	$selected = @($all | Where-Object { Test-StoreFilter $_ $cfg.filter })
236	Write-Step ("after filter: {0}" -f $selected.Count)
237	foreach ($s in $selected) {
238	  $disp = Get-DisplayName $s $cfg.storeNameMap
239	  $ip = if ($s.ip) { $s.ip } else { '(no-ip)' }
240	  Write-Host ("  - {0} | {1} => Feishu[{2}] | {3} | {4}" -f $s.storeId, $s.storeName, $disp, $s.platformName, $ip)
241	}
242	
243	if ($ListOnly) {
244	  Write-Step "ListOnly done."
245	  exit 0
246	}
247	
248	if ($selected.Count -eq 0) {
249	  throw "No stores matched filter. Adjust requireIp / platformContains / excludeStoreIds."
250	}
251	
252	$useDryRun = if ($null -ne $DryRun) { [bool]$DryRun } else { [bool]$cfg.options.dryRun }
253	$bizDate = Get-BizDate $cfg.options.dateMode
254	Write-Step ("bizDate={0} dryRun={1}" -f $bizDate, $useDryRun)
255	
256	$summary = @()
257	$allCampaignRows = @()
258	$scrapeOneLine = ($scrapeJs -replace '\r?\n', ' ' -replace '\s+', ' ').Trim()
259	
260	$analysisEnabled = $true
261	$lowRoi = 3.0
262	$writeSummaryFeishu = $true
263	if ($cfg.analysis) {
264	  if ($null -ne $cfg.analysis.enabled) { $analysisEnabled = [bool]$cfg.analysis.enabled }
265	  if ($null -ne $cfg.analysis.lowRoiThreshold) { $lowRoi = [double]$cfg.analysis.lowRoiThreshold }
266	  if ($null -ne $cfg.analysis.writeSummaryToFeishu) { $writeSummaryFeishu = [bool]$cfg.analysis.writeSummaryToFeishu }
267	}
268	
269	foreach ($store in $selected) {
270	  $sid = $store.storeId
271	  $sname = $store.storeName
272	  $display = Get-DisplayName $store $cfg.storeNameMap
273	  $adsUrl = Get-AdsUrl $store $cfg.adsUrl
274	  $item = [ordered]@{
275	    storeId     = $sid
276	    storeName   = $sname
277	    displayName = $display
278	    ok          = $false
279	    rows        = 0
280	    written     = 0
281	    error       = $null
282	  }
283	
284	  Write-Step ("==== START {0} ({1}) => {2} ====" -f $sname, $sid, $display)
285	  try {
286	    Write-Step "  open store..."
287	    Write-Host (Invoke-Ziniao @('store', 'open', '--id', $sid, '--url', $adsUrl))
288	    Start-Sleep -Milliseconds ([int]$cfg.options.waitAfterOpenMs)
289	
290	    Write-Step "  visit ads page..."
291	    Write-Host (Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $adsUrl, '--wait-until', 'networkidle', '--timeout', '90000'))
292	    Start-Sleep -Milliseconds ([int]$cfg.options.waitAfterVisitMs)
293	
294	    Write-Step "  page exec scrape..."
295	    $execOut = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $scrapeOneLine, '--timeout', '60000')
296	    Write-Host $execOut
297	
298	    $payload = $null
299	    if ($execOut -match '(?s)\{[\s\S]*"ok"\s*:[\s\S]*\}') {
300	      try { $payload = $Matches[0] | ConvertFrom-Json } catch { }
301	    }
302	    if (-not $payload) {
303	      try { $payload = $execOut.Trim() | ConvertFrom-Json } catch { }
304	    }
305	    if (-not $payload -or -not $payload.ok) {
306	      $err = if ($payload -and $payload.error) { [string]$payload.error } else { "scrape failed" }
307	      throw $err
308	    }
309	
310	    $rows = @()
311	    foreach ($r in @($payload.rows)) {
312	      $rows += [pscustomobject]@{
313	        date      = $bizDate
314	        store     = $display
315	        storeId   = $sid
316	        campaign  = [string]$r.campaign
317	        spend     = if ($null -ne $r.spend) { $r.spend } else { 0 }
318	        orders    = if ($null -ne $r.orders) { $r.orders } else { 0 }
319	        roi       = if ($null -ne $r.roi) { $r.roi } else { 0 }
320	        revenue   = if ($null -ne $r.revenue) { $r.revenue } else { 0 }
321	        sourceUrl = [string]$payload.url
322	        status    = 'success'
323	      }
324	    }
325	    $item.rows = $rows.Count
326	    $allCampaignRows += $rows
327	    Write-Step ("  scraped {0} rows, write Feishu..." -f $rows.Count)
328	    $w = Write-FeishuRows $cfg.feishu $rows $useDryRun
329	    $item.written = $w.written
330	    $item.ok = $true
331	    Write-Step ("  done written={0}" -f $w.written)
332	  }
333	  catch {
334	    $item.error = [string]$_
335	    Write-Step ("  FAIL: {0}" -f $_)
336	  }
337	  finally {
338	    if ($cfg.options.closeAfter) {
339	      try {
340	        Write-Step "  close store..."
341	        $null = Invoke-Ziniao @('store', 'close', '--id', $sid)
342	      } catch { }
343	    }
344	    Start-Sleep -Milliseconds ([int]$cfg.options.delayBetweenStoresMs)
345	  }
346	  $summary += [pscustomobject]$item
347	}
348	
349	Write-Step "======== SUMMARY ========"
350	$summary | Format-Table storeName, displayName, ok, rows, written, error -AutoSize
351	$okCount = @($summary | Where-Object { $_.ok }).Count
352	Write-Step ("OK {0} / {1}" -f $okCount, $summary.Count)
