# We won't run full dry - just param parse by running a tiny probe
$script = @'
param([string]$DryRun = "")
function Convert-DryRunFlag([string]$raw) {
  if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
  switch -Regex ($raw.Trim()) {
    '^(?i:true|1|yes|y|\$true)$'  { return $true }
    '^(?i:false|0|no|n|\$false)$' { return $false }
    default { throw "Invalid -DryRun value '$raw'" }
  }
}
$p = Convert-DryRunFlag $DryRun
"parsed=$p isNull=$($null -eq $p)"
'@
$tmp = Join-Path $env:TEMP 'dryrun-test.ps1'
Set-Content -Path $tmp -Value $script -Encoding UTF8
@(
  @('-DryRun','true'),
  @('-DryRun','false'),
  @('-DryRun','$true'),
  @('-DryRun','TRUE'),
  @()
) | ForEach-Object {
  $args = $_
  $out = & powershell -NoProfile -File $tmp @args 2>&1
  Write-Host ("args=[{0}] => {1}" -f ($args -join ' '), ($out -join ' '))
}
Remove-Item $tmp -Force

