file.content:
if ($selected.Count -eq 0) {
  throw "No stores matched filter. Adjust requireIp / platformContains / excludeStoreIds."
}

function Convert-DryRunFlag([string]$raw) {
  if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
  switch -Regex ($raw.Trim()) {
    '^(?i:true|1|yes|y|\$true)$'  { return $true }
    '^(?i:false|0|no|n|\$false)$' { return $false }
    default { throw "Invalid -DryRun value '$raw' (use true/false, or omit to use config)" }
  }
}
$dryRunParsed = Convert-DryRunFlag $DryRun
$useDryRun = if ($null -ne $dryRunParsed) { [bool]$dryRunParsed } else { [bool]$cfg.options.dryRun }
$bizDate = Get-BizDate $cfg.options.dateMode
Write-Step ("bizDate={0} dryRun={1}" -f $bizDate, $useDryRun)

$summary = @()
$allCampaignRows = @()
$scrapeOneLine = ($scrapeJs -replace '\r?\n', ' ' -replace '\s+', ' ').Trim()

$analysisEnabled = $true
$lowRoi = 3.0
$writeSummaryFeishu = $true
if ($cfg.analysis) {
  if ($null -ne $cfg.analysis.enabled) { $analysisEnabled = [bool]$cfg.analysis.enabled }
  if ($null -ne $cfg.analysis.lowRoiThreshold) { $lowRoi = [double]$cfg.analysis.lowRoiThreshold }
  if ($null -ne $cfg.analysis.writeSummaryToFeishu) { $writeSummaryFeishu = [bool]$cfg.analysis.writeSummaryToFeishu }
}

foreach ($store in $selected) {
  $sid = $store.storeId
  $sname = $store.storeName
  $display = Get-DisplayName $store $cfg.storeNameMap
  $adsUrl = Get-AdsUrl $store $cfg.adsUrl
  $item = [ordered]@{
    storeId     = $sid
    storeName   = $sname
    displayName = $display
    ok          = $false
    rows        = 0
    written     = 0
    error       = $null
  }

  Write-Step ("==== START {0} ({1}) => {2} ====" -f $sname, $sid, $display)
  try {
    Write-Step "  open store..."
    Write-Host (Invoke-Ziniao @('store', 'open', '--id', $sid, '--url', $adsUrl))
    Start-Sleep -Milliseconds ([int]$cfg.options.waitAfterOpenMs)

    Write-Step "  visit ads page..."
    Write-Host (Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $adsUrl, '--wait-until', 'networkidle', '--timeout', '90000'))
    Start-Sleep -Milliseconds ([int]$cfg.options.waitAfterVisitMs)

    Write-Step "  page exec scrape..."
    $execOut = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $scrapeOneLine, '--timeout', '60000')
    Write-Host $execOut

    $payload = $null
    if ($execOut -match '(?s)\{[\s\S]*"ok"\s*:[\s\S]*\}') {
      try { $payload = $Matches[0] | ConvertFrom-Json } catch { }
    }
    if (-not $payload) {
      try { $payload = $execOut.Trim() | ConvertFrom-Json } catch { }
    }
    if (-not $payload -or -not $payload.ok) {
      $err = if ($payload -and $payload.error) { [string]$payload.error } else { "scrape failed" }
      throw $err
    }

    $rows = @()
    foreach ($r in @($payload.rows)) {
      $rows += [pscustomobject]@{
        date      = $bizDate
        store     = $display
        storeId   = $sid
        campaign  = [string]$r.campaign
        spend     = if ($null -ne $r.spend) { $r.spend } else { 0 }
        orders    = if ($null -ne $r.orders) { $r.orders } else { 0 }
        roi       = if ($null -ne $r.roi) { $r.roi } else { 0 }
        revenue   = if ($null -ne $r.revenue) { $r.revenue } else { 0 }
        sourceUrl = [string]$payload.url
        status    = 'success'
      }
    }
    $item.rows = $rows.Count
    $allCampaignRows += $rows
    Write-Step ("  scraped {0} rows, write Feishu..." -f $rows.Count)
    $w = Write-FeishuRows $cfg.feishu $rows $useDryRun
    $item.written = $w.written
    $item.ok = $true
    Write-Step ("  done written={0}" -f $w.written)
  }
  catch {
    $item.error = [string]$_
    Write-Step ("  FAIL: {0}" -f $_)
  }
  finally {

input.old_string:
/**
 * 在 TikTok 广告数据面板页执行，返回广告系列行 JSON 字符串
 * 由 ziniao-cli page exec 注入；勿依赖 chrome extension API
 */
(function () {
  function cleanText(t) {
    return String(t ?? '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function parseNumber(value) {
    if (value == null || value === '') return null;
    if (typeof value === 'number' && Number.isFinite(value)) return value;
    let s = String(value).trim();
    if (!s || s === '-' || s === '—') return null;
    s = s
      .replace(/[,\s]/g, '')
      .replace(/[¥$€£￥USD|GBP|EUR]/gi, '')
      .replace(/%/g, '');
    const paren = s.match(/^\((.+)\)$/);
    if (paren) s = `-${paren[1]}`;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  }

  const HEADER_ALIASES = {
    campaign: ['品名', '广告系列', '广告系列名称', '系列名称', 'campaign', 'campaign name', 'product', '名称'],
    spend: ['广告花费', '广告成本', '花费', '成本', '消耗', 'cost', 'spend', 'ad spend'],
    orders: ['销量', '订单', 'sku 订单', 'sku订单', 'orders', 'units', 'units sold'],
    roi: ['roi', 'roas', '投资回报率', '投资回报', '回报率'],
    revenue: ['销售额', '总收入', '销售收入', '收入', 'gmv', 'revenue', 'gross revenue']
  };

  function matchHeaderField(headerText) {
    const t = cleanText(headerText).toLowerCase();
    if (!t) return null;
    const order = ['roi', 'spend', 'orders', 'revenue', 'campaign'];
    for (const field of order) {
      for (const a of HEADER_ALIASES[field]) {
        const al = a.toLowerCase();
        if (!(t === al || t.includes(al) || (al.length >= 2 && al.includes(t)))) continue;
        if (field === 'spend' && /平均下单|cost per|per order|\bcpc\b|\bcpa\b/.test(t)) continue;
        return field;
      }
    }
    return null;
  }

  function parseHtmlTable(table) {
    let headerRow = table.querySelector('thead tr') || table.querySelector('tr');
    if (!headerRow) return [];
    const headerCells = [...headerRow.querySelectorAll('th, td')];
    const fields = headerCells.map((c) => matchHeaderField(c.innerText || ''));
    if (!fields.some(Boolean)) return [];
    const bodyRows = table.querySelectorAll('tbody tr');
    const rows = bodyRows.length ? [...bodyRows] : [...table.querySelectorAll('tr')].slice(1);
    const results = [];
    for (const tr of rows) {
      const cells = [...tr.querySelectorAll('td, th')];
      if (!cells.length) continue;
      const row = {};
      fields.forEach((field, i) => {
        if (!field || !cells[i]) return;
        const text = cleanText(cells[i].innerText || '');
        row[field] = field === 'campaign' ? text : parseNumber(text) ?? text;
      });
      if (row.campaign || row.spend != null || row.revenue != null) results.push(row);
    }
    return results;
  }

  function scoreRows(rows) {
    if (!rows?.length) return 0;
    let s = rows.length;
    for (const r of rows.slice(0, 5)) {
      if (r.campaign) s += 2;
      if (r.spend != null && r.spend !== '') s += 2;
      if (r.roi != null) s += 2;
      if (r.revenue != null) s += 2;
    }
    return s;
  }

  let best = [];
  let source = 'none';
  for (const table of document.querySelectorAll('table')) {
    const rows = parseHtmlTable(table);
    if (scoreRows(rows) > scoreRows(best)) {
      best = rows;
      source = 'html-table';
    }
  }

  // 过滤汇总行
  best = best.filter((r) => {
    const c = cleanText(r.campaign || '').toLowerCase();
    if (!c) return false;
    if (['total', '合计', '总计', '汇总', 'summary', 'all'].includes(c)) return false;
    return true;
  });

  // 探测店铺展示名
  let storeHint = '';
  for (const el of [...document.querySelectorAll('div, span, h1, h2')].slice(0, 300)) {
    const t = cleanText(el.innerText || '');
    if (t.length > 5 && t.length < 100 && /主要账号|主账号/.test(t)) {
      storeHint = t.replace(/主要账号|主账号/g, '').trim();
      break;
    }
  }

  return JSON.stringify({
    ok: best.length > 0,
    source,
    storeHint,
    url: location.href,
    title: document.title,
    rows: best,
    error: best.length ? null : '未识别到广告表格，请确认已进入广告数据面板'
  });
})();

