function Invoke-Ziniao([string[]]$CliArgs) {
  $prev = $ErrorActionPreference
  $ErrorActionPreference = 'Continue'
  try {
    $out = & ziniao-cli @CliArgs 2>&1
    $text = ($out | ForEach-Object { "$_" }) -join "`n"
    return $text
  } finally {
    $ErrorActionPreference = $prev
  }
}

function ConvertTo-ScrapeOneLine([string]$js) {
  # // comments become catastrophic when newlines are removed — strip first
  $s = [regex]::Replace($js, '/\*[\s\S]*?\*/', ' ')
  $s = [regex]::Replace($s, '(?m)^\s*//.*$', '')
  $s = [regex]::Replace($s, '(?m)([^:"''\\])//[^\r\n]*', '$1')
  $s = ($s -replace '\r?\n', ' ' -replace '\s+', ' ').Trim()
  if ($s -notmatch '\)\s*\(\s*\)\s*;?\s*$' -and $s -notmatch '\}\s*\)\s*\(\s*\)\s*;?\s*$') {
    Write-Step "WARN scrape script may be truncated (len=$($s.Length))"
  }
  return $s
}

function ConvertFrom-JsonSafe([string]$text) {
  if ([string]::IsNullOrWhiteSpace($text)) { return $null }
  try { return ($text | ConvertFrom-Json) } catch { return $null }
}

function Get-ScrapePayload([string]$execOut) {
  # ziniao-cli wraps CDP result: { ok, data: { data: { result: { type, value } | exceptionDetails } } }
  # Our script returns JSON.stringify({ ok, rows, ... }) so value is a JSON string.
  $root = ConvertFrom-JsonSafe $execOut
  if (-not $root) {
    if ($execOut -match '(?s)(\{[^{}]*"rows"\s*:\s*\[[\s\S]*?\}\s*)$') {
      $root = ConvertFrom-JsonSafe $Matches[1]
    }
  }
  if (-not $root) { return $null }

  $candidates = New-Object System.Collections.Generic.List[object]
  $candidates.Add($root) | Out-Null

  if ($root.data) {
    $candidates.Add($root.data) | Out-Null
    if ($root.data.data) { $candidates.Add($root.data.data) | Out-Null }
    if ($root.data.result) { $candidates.Add($root.data.result) | Out-Null }
    if ($root.data.data -and $root.data.data.result) { $candidates.Add($root.data.data.result) | Out-Null }
  }

  foreach ($c in $candidates) {
    if ($null -eq $c) { continue }
    if ($c.PSObject.Properties.Name -contains 'exceptionDetails' -and $c.exceptionDetails) {
      $ex = $c.exceptionDetails
      $msg = if ($ex.exception -and $ex.exception.description) { [string]$ex.exception.description }
             elseif ($ex.text) { [string]$ex.text }
             else { 'page exec exception' }
      return [pscustomobject]@{ ok = $false; rows = @(); error = $msg; source = 'exception' }
    }
    if ($c.PSObject.Properties.Name -contains 'value') {
      $v = $c.value
      if ($v -is [string]) {
        $inner = ConvertFrom-JsonSafe $v
        if ($inner -and ($inner.PSObject.Properties.Name -contains 'rows' -or $inner.PSObject.Properties.Name -contains 'ok')) {
          return $inner
        }
      } elseif ($v -and ($v.PSObject.Properties.Name -contains 'rows')) {
        return $v
      }
    }
    if (($c.PSObject.Properties.Name -contains 'rows') -and ($c.PSObject.Properties.Name -contains 'ok')) {
      # Prefer our scrape shape over ziniao outer {ok:true} without rows
      return $c
    }
  }

  # Fallback: search for embedded scrape JSON with rows key
  if ($execOut -match '(?s)(\{\s*"ok"\s*:\s*(?:true|false)\s*,\s*"source"\s*:[\s\S]*?"rows"\s*:\s*\[[\s\S]*?\})') {
    $inner = ConvertFrom-JsonSafe $Matches[1]
    if ($inner) { return $inner }
  }

  return [pscustomobject]@{
    ok    = $false
    rows  = @()
    error = "unrecognized page exec payload"
    source = 'parse'
    rawPreview = if ($execOut.Length -gt 400) { $execOut.Substring(0, 400) } else { $execOut }
  }
}

