  $sname = $store.storeName
  $display = Get-DisplayName $store $cfg.storeNameMap
  $adsUrl = Get-AdsUrl $store $cfg.adsUrl
  $item = [ordered]@{
    storeId     = $sid
    storeName   = $sname
    displayName = $display
    ok          = $false
    rows        = 0
    written     = 0
    error       = $null
  }

  Write-Step ("==== START {0} ({1}) => {2} ====" -f $sname, $sid, $display)
  try {
    Write-Step "  open store..."
    Write-Host (Invoke-Ziniao @('store', 'open', '--id', $sid, '--url', $adsUrl))
    Start-Sleep -Milliseconds ([int]$cfg.options.waitAfterOpenMs)

    Write-Step "  visit ads page..."
    Write-Host (Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $adsUrl, '--wait-until', 'networkidle', '--timeout', '90000'))
    Start-Sleep -Milliseconds ([int]$cfg.options.waitAfterVisitMs)

    Write-Step "  page exec scrape..."
    $execOut = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $scrapeOneLine, '--timeout', '60000')
    Write-Host $execOut

    $payload = $null
    if ($execOut -match '(?s)\{[\s\S]*"ok"\s*:[\s\S]*\}') {
      try { $payload = $Matches[0] | ConvertFrom-Json } catch { }
    }
    if (-not $payload) {
      try { $payload = $execOut.Trim() | ConvertFrom-Json } catch { }
    }
    if (-not $payload -or -not $payload.ok) {
      $err = if ($payload -and $payload.error) { [string]$payload.error } else { "scrape failed" }
      throw $err
    }

    $rows = @()
    foreach ($r in @($payload.rows)) {
      $rows += [pscustomobject]@{
        date      = $bizDate
        store     = $display
        storeId   = $sid
        campaign  = [string]$r.campaign
        spend     = if ($null -ne $r.spend) { $r.spend } else { 0 }
        orders    = if ($null -ne $r.orders) { $r.orders } else { 0 }
        roi       = if ($null -ne $r.roi) { $r.roi } else { 0 }
        revenue   = if ($null -ne $r.revenue) { $r.revenue } else { 0 }
        sourceUrl = [string]$payload.url
        status    = 'success'
      }
    }
    $item.rows = $rows.Count
    $allCampaignRows += $rows
    Write-Step ("  scraped {0} rows, write Feishu..." -f $rows.Count)
    $w = Write-FeishuRows $cfg.feishu $rows $useDryRun
    $item.written = $w.written
    $item.ok = $true
    Write-Step ("  done written={0}" -f $w.written)
  }

